-- research_tests_2026-10-11g.sql — exit re-simulation on every base strategy's real entries (founder: "are we testing all strategies with different sl, tp, trail?").
INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('S16-exit-resim', 'X', 'Exit grid re-simulated on 1.15M real RTH entries of 419 base strategies (minute paths rebuilt from bars_1m): SL {10,25,none} × TP {20,60,none} × trail {15,40,none} × time-stop {60,none} + 15:59 close; chosen per base on train (<2025-03), scored on test', 'NQ', '2021–2026', 1145032, 0.92, NULL, NULL, 'no edge', 'The engine''s own exits were destroying value: median test PF 0.53 → 0.92 with the train-chosen exit, 89% of bases improve (+$2,873 mean); the chosen exit is "hold to the close" for 213 bases and "wide 25-pt stop only" for 140 — tight stops, targets, trails and BE triggers lose. But even the TEST ORACLE (exit chosen with hindsight on the test period) gives only 22.9% of bases PF>1.2 and a median PF of 1.09; train-chosen: 8.1% PF>1.2 on test, 0 of 419 bases PF>1.3 in both halves. Exit optimisation stops the bleeding; it cannot create an edge the entries do not have. Also: walk_forward.sh (choose the best variant per family on the prior 3/6/12 months) — 82 groups, 10 positive OOS, −$48k net: in-sample winners do not carry.', '2026-10-11')
